using System;using System.IO;using System.Linq;using System.Reflection;using System.Drawing;using System.Windows.Forms;using V15Voice;
public static class StudioLayoutTests {
 static int count,code;static object F(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static object C(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,a);}static void Check(bool b,string n){if(!b)throw new Exception(n);Console.WriteLine("PASS "+n);count++;}
 static Rectangle Screen(Control c){return c.RectangleToScreen(c.ClientRectangle);}static bool OnScreen(Control c){if(!c.Visible)return false;var r=Screen(c);for(Control p=c.Parent;p!=null;p=p.Parent)if(!Screen(p).Contains(r))return false;return true;}
 static void Capture(Form f,string n){Application.DoEvents();f.Refresh();using(var b=new Bitmap(f.Width,f.Height)){using(var g=Graphics.FromImage(b))g.CopyFromScreen(f.Location,Point.Empty,f.Size);b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"validation",n+".png"));}}
 [STAThread]public static void Main(){Application.EnableVisualStyles();var f=new MainForm();f.Shown+=(s,e)=>{try{
  var tabs=(TabControl)F(f,"tabs");var settings=(TabControl)F(f,"studioSettings");var voice=(ComboBox)F(f,"voices");var card=(Control)F(f,"studioVoiceCard");var actions=(Control)F(f,"studioActions");
  Check(f.Icon!=null&&f.GetType().Assembly.GetManifestResourceNames().Contains("V15VoiceStudio.Icon"),"New icon is embedded and loaded by window");Check(settings.TabCount==4&&settings.TabPages.Cast<TabPage>().Select(x=>x.Text).SequenceEqual(new[]{"TXT & đích","Căn SRT","Ngắt nghỉ","Hơi thở"}),"Four independent settings tabs");
  string txt=Path.Combine(Path.GetTempPath(),"layout205-"+Guid.NewGuid().ToString("N")+".txt");File.WriteAllText(txt,"This is an example script. A second sentence describes the scene in more detail.");C(f,"LoadFile",txt);((CheckBox)F(f,"textTargetEnabled")).Checked=true;((TextBox)F(f,"textTargetValue")).Text="00:16";
  Check(settings.SelectedIndex==0,"Opening TXT selects duration tab");Capture(f,"studio205-default");Console.WriteLine("TARGET LABEL "+((Control)F(f,"textTargetInfo")).Bounds+" max="+((Control)F(f,"textTargetInfo")).MaximumSize+" parent="+((Control)F(f,"textTargetInfo")).Parent.ClientSize);
  foreach(var size in new[]{new Size(1440,960),new Size(1280,850),new Size(1100,740)}){
   f.Size=size;f.Location=new Point(0,0);Application.DoEvents();var anchor=Screen(card);
   foreach(string n in new[]{"languagePicker","family","styleFilter","voices"}){var c=(Control)F(f,n);Console.WriteLine(n+" "+c.Bounds+" visible="+c.Visible+" onscreen="+OnScreen(c));Check(OnScreen(c)&&c.Width>=170&&c.Height>=24,"Voice picker reachable "+n+" at "+size);}
   Check(card.Controls.OfType<Button>().Any(b=>b.Text=="Chi tiết giọng"&&OnScreen(b)),"Full voice description remains accessible at "+size);Check(settings.SelectedTab.ClientSize.Height>=100,"Settings viewport remains usable at "+size);Check(OnScreen((Control)F(f,"preview"))&&OnScreen((Control)F(f,"render"))&&OnScreen((Control)F(f,"cancel"))&&OnScreen((Control)F(f,"openOutput")),"Primary actions visible at "+size);
   foreach(TabPage page in settings.TabPages){settings.SelectedTab=page;Application.DoEvents();var flow=(ScrollableControl)page.Controls[0];Check(!flow.HorizontalScroll.Visible,"No horizontal scrolling required: "+page.Text+" "+size);flow.AutoScrollPosition=new Point(0,5000);Application.DoEvents();Check(Screen(card)==anchor&&OnScreen(voice),"Settings scroll never moves voice card: "+page.Text+" "+size);flow.AutoScrollPosition=Point.Empty;}
   settings.SelectedIndex=0;((Label)F(f,"textTargetInfo")).Text=String.Join("\r\n",Enumerable.Repeat("Long status remains inside its own scrolling box.",40));((Label)F(f,"proseTiming")).Text=String.Join("\r\n",Enumerable.Repeat("Rendering progress with detailed timings.",40));Application.DoEvents();
   Check(Screen(card)==anchor&&OnScreen(voice),"Long diagnostics do not displace voice picker at "+size);var pane=(Panel)((Control)F(f,"textTargetInfo")).Parent;Check(pane.Height==116&&pane.VerticalScroll.Visible,"Diagnostic viewport stays bounded and scrolls at "+size);Capture(f,"studio205-"+size.Width);
  }
  f.Size=new Size(1440,960);settings.SelectedIndex=3;((ComboBox)F(f,"breathMode")).SelectedIndex=1;Application.DoEvents();Check(((Control)F(f,"breathSettings")).Visible,"Custom breath controls reachable in breath tab");Capture(f,"studio205-breath");
  var saved=(VoiceSettings)C(f,"CaptureSettings");Check(saved.Breathing==1,"Breath choice still reaches shared queue settings");C(f,"SetBusy",true);Check(!voice.Enabled&&!((Control)F(f,"languagePicker")).Enabled&&((Control)F(f,"cancel")).Enabled,"All voice selectors disabled safely while rendering, stop remains enabled");C(f,"SetBusy",false);Check(voice.Enabled&&((Control)F(f,"languagePicker")).Enabled,"Selectors unlock after rendering");
  C(f,"LoadSample");C(f,"SelectStudioSettings",false);settings.SelectedIndex=1;((ComboBox)F(f,"mode")).SelectedIndex=2;Application.DoEvents();Check(((Control)F(f,"anchoredControls")).Visible,"V15.6 controls remain reachable in SRT tab");Capture(f,"studio205-srt");
  Console.WriteLine("TOTAL LAYOUT "+count+" passed.");
 }catch(Exception x){Console.WriteLine(x);code=1;}finally{f.Close();}};Application.Run(f);Environment.Exit(code);}
}
